package searchapi

import "testing"

func TestAccountIDFromSubject(t *testing.T) {
	cases := map[string]string{
		"account:test-account-id": "test-account-id",
		"01JABCDEF":               "01JABCDEF",
		"":                        "",
	}
	for sub, want := range cases {
		if got := accountIDFromSubject(sub); got != want {
			t.Fatalf("accountIDFromSubject(%q) = %q, want %q", sub, got, want)
		}
	}
}
package searchapi

import (
	"context"
	"fmt"
	"net/http"
	"strings"
)

// AuthResult holds the verified caller identity.
type AuthResult struct {
	AccountID string // Verified JWT sub, forwarded to the repo resolver as the authz subject.
	Token     string // Raw verified core JWT; forwarded only to the core that minted it.
	Issuer    string // Verified JWT iss (one of the trusted issuers).
