// Authors maps fact id → display handle (account id when no handle was on the
// advancing token) for one branch's projection.
func (s *Store) Authors(ctx context.Context, repoID, branch string) (map[string]string, error) {
	rows, err := s.pool.Query(ctx,
		`SELECT fact_id, created_by, created_by_handle FROM brain_facts WHERE repo_id=$1 AND branch=$2`,
		repoID, branch)
	if err != nil {
		return nil, fmt.Errorf("store: authors: %w", err)
	}
	defer rows.Close()
	out := map[string]string{}
	for rows.Next() {
		var id, acct, handle string
		if err := rows.Scan(&id, &acct, &handle); err != nil {
			return nil, fmt.Errorf("store: authors: %w", err)
		}
		if handle == "" {
			handle = acct
		}
		out[id] = handle
	}
	return out, rows.Err()
}
