func TestWireAdvanceAndCurrent(t *testing.T) {
	s, repoID := testServer(t)
	blob := ndjsonBytes(t, "fact a")
	body, _ := json.Marshal(map[string]any{"branch": "main", "oldRef": "", "old_ref": "", "data": blob})
	rec := httptest.NewRecorder()
	req := httptest.NewRequest("POST", "/repos/"+repoID+"/brain/facts/advance", bytes.NewReader(body))
	req.Header.Set("Authorization", "Bearer tok1")
	s.Handler().ServeHTTP(rec, req)
	if rec.Code != 200 {
		t.Fatalf("advance: %d %s", rec.Code, rec.Body)
	}
	var adv struct {
		NewRef  string `json:"newRef"`
		Version int64  `json:"version"`
		Changed *bool  `json:"changed"`
	}
	if err := json.Unmarshal(rec.Body.Bytes(), &adv); err != nil || adv.NewRef == "" || adv.Changed == nil || !*adv.Changed {
		t.Fatalf("advance body: %s err=%v", rec.Body, err)
	}

	rec2 := httptest.NewRecorder()
	req2 := httptest.NewRequest("GET", "/repos/"+repoID+"/brain/facts?branch=main", nil)
	req2.Header.Set("Authorization", "Bearer tok1")
	s.Handler().ServeHTTP(rec2, req2)
	var cur struct {
		Found   bool   `json:"found"`
		Ref     string `json:"ref"`
		Version int64  `json:"version"`
		Data    []byte `json:"data"`
	}
	if err := json.Unmarshal(rec2.Body.Bytes(), &cur); err != nil || !cur.Found || cur.Ref != adv.NewRef || string(cur.Data) != string(blob) {
		t.Fatalf("current body: %s err=%v", rec2.Body, err)
	}
}

func TestWireAdvanceLegacyOldRefOnly(t *testing.T) {
	// released clients send BOTH spellings; an old client may send only old_ref.
	s, repoID := testServer(t)
	blob1 := ndjsonBytes(t, "fact a")
	ref1 := mustAdvance(t, s, repoID, "", blob1)
	blob2 := ndjsonBytes(t, "fact a", "fact b")
	body, _ := json.Marshal(map[string]any{"branch": "main", "old_ref": ref1, "data": blob2})
	rec := postAdvance(t, s, repoID, body)
	if rec.Code != 200 {
		t.Fatalf("old_ref-only advance must CAS from old_ref, got %d %s", rec.Code, rec.Body)
	}
}

func TestWireConflictIs412(t *testing.T) {
	s, repoID := testServer(t)
	blob1 := ndjsonBytes(t, "fact a")
	_ = mustAdvance(t, s, repoID, "", blob1)
	body, _ := json.Marshal(map[string]any{"branch": "main", "oldRef": "facts-stale", "old_ref": "facts-stale", "data": ndjsonBytes(t, "fact b")})
	rec := postAdvance(t, s, repoID, body)
	if rec.Code != http.StatusPreconditionFailed {
		t.Fatalf("stale advance: %d, want 412", rec.Code)
	}
}

func TestWireGuards(t *testing.T) {
	s, repoID := testServer(t)
	cases := []struct {
		name string
		do   func() *httptest.ResponseRecorder
		want int
	}{
		{"no auth", func() *httptest.ResponseRecorder {
			rec := httptest.NewRecorder()
			s.Handler().ServeHTTP(rec, httptest.NewRequest("GET", "/repos/"+repoID+"/brain/facts?branch=main", nil))
			return rec
		}, 401},
		{"forbidden repo", func() *httptest.ResponseRecorder { return getFacts(t, s, "01ZZZZZZZZZZZZZZZZZZZZZZZZ", "main") }, 403},
		{"bad repo id", func() *httptest.ResponseRecorder { return getFacts(t, s, "not-a-ulid", "main") }, 400},
		{"empty branch", func() *httptest.ResponseRecorder { return getFacts(t, s, repoID, "") }, 400},
		{"branch over 512 bytes", func() *httptest.ResponseRecorder { return getFacts(t, s, repoID, strings.Repeat("b", 513)) }, 400},
	}
	for _, c := range cases {
		if rec := c.do(); rec.Code != c.want {
			t.Fatalf("%s: %d, want %d (%s)", c.name, rec.Code, c.want, rec.Body)
		}
	}
}
