```go
type Server struct {
	store  *store.Store
	auth   authenticator
	access repoAccess
	logger zerolog.Logger
}

type repoAccessFunc func(ctx context.Context, caller AuthResult, repoID string, write bool) error

func (f repoAccessFunc) Check(ctx context.Context, caller AuthResult, repoID string, write bool) error {
	return f(ctx, caller, repoID, write)
}

func NewServer(st *store.Store, auth authenticator, access repoAccess, logger zerolog.Logger) *Server {
	return &Server{store: st, auth: auth, access: access, logger: logger}
}

func (s *Server) Handler() http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /openapi.yaml", s.handleOpenAPI)
	mux.HandleFunc("GET /brain/v1/health", s.handleHealth)
	mux.HandleFunc("GET /repos/{repo_id}/brain/facts", s.handleCurrent)
	mux.HandleFunc("POST /repos/{repo_id}/brain/facts/advance", s.handleAdvance)
	mux.HandleFunc("GET /repos/{repo_id}/brain/memories", s.handleMemories) // Task 8; stub 503 until then
	return s.loggingMiddleware(mux)
}

var ulidPattern = regexp.MustCompile(`^[0-9A-HJKMNP-TV-Z]{26}$`)

const maxBranchBytes = 512 // lockstep with entire-brain factsync/httpserver.go:211

// guard authenticates, authorizes, and validates the repo/branch coordinates.
// Order: 401 (authn) → 403 (authz, before existence) → 400 (coordinates).
func (s *Server) guard(w http.ResponseWriter, r *http.Request, write bool) (AuthResult, string, string, bool) {
	caller, err := s.auth(r.Context(), r)
	if err != nil {
		writeJSONError(w, http.StatusUnauthorized, "Unauthorized")
		return AuthResult{}, "", "", false
	}
	repoID := r.PathValue("repo_id")
	if !ulidPattern.MatchString(repoID) {
		writeJSONError(w, http.StatusBadRequest, "invalid repo id")
		return AuthResult{}, "", "", false
	}
	if err := s.access.Check(r.Context(), *caller, repoID, write); err != nil {
		writeJSONError(w, http.StatusForbidden, "Forbidden")
		return AuthResult{}, "", "", false
	}
	branch := strings.TrimSpace(r.URL.Query().Get("branch"))
	return *caller, repoID, branch, true
}
```

`internal/httpapi/facts.go`:

```go
type advanceRequest struct {
	Branch       string `json:"branch"`
	OldRef       string `json:"oldRef"`
	OldRefLegacy string `json:"old_ref"` // released clients send both; old ones only this
	Data         []byte `json:"data"`
}

type advanceResponse struct {
	NewRef  string `json:"newRef"`
	Version int64  `json:"version"`
	Changed bool   `json:"changed"`
}

type currentResponse struct {
	Found   bool   `json:"found"`
	Ref     string `json:"ref,omitempty"`
	Version int64  `json:"version,omitempty"`
	Data    []byte `json:"data,omitempty"`
	// Authors is additive (fact id → display handle): released clients ignore
	// it; the plugin's pull step stamps it onto merged records.
	Authors map[string]string `json:"authors,omitempty"`
}

const maxAdvanceBody = 32 << 20

func (s *Server) handleCurrent(w http.ResponseWriter, r *http.Request) {
	_, repoID, branch, ok := s.guard(w, r, false)
	if !ok {
		return
	}
	if err := validateBranch(branch); err != nil {
		writeJSONError(w, http.StatusBadRequest, err.Error())
		return
	}
	ref, version, data, found, err := s.store.Current(r.Context(), repoID, branch)
	if err != nil {
		s.logger.Error().Err(err).Msg("current")
		writeJSONError(w, http.StatusInternalServerError, "internal error")
		return
	}
	var authors map[string]string
	if found {
		if authors, err = s.store.Authors(r.Context(), repoID, branch); err != nil {
			authors = nil // additive field: a projection read failure must not fail the sync read path
			s.logger.Warn().Err(err).Msg("authors lookup failed; serving head without attribution")
		}
	}
	writeJSON(w, http.StatusOK, currentResponse{Found: found, Ref: ref, Version: version, Data: data, Authors: authors})
}

func (s *Server) handleAdvance(w http.ResponseWriter, r *http.Request) {
	caller, repoID, _, ok := s.guard(w, r, true)
	if !ok {
		return
	}
	var req advanceRequest
	if err := json.NewDecoder(io.LimitReader(r.Body, maxAdvanceBody)).Decode(&req); err != nil {
		writeJSONError(w, http.StatusBadRequest, "invalid body")
		return
	}
	branch := strings.TrimSpace(req.Branch)
	if err := validateBranch(branch); err != nil {
		writeJSONError(w, http.StatusBadRequest, err.Error())
		return
	}
	if len(req.Data) == 0 {
		writeJSONError(w, http.StatusBadRequest, "empty data")
		return
	}
	oldRef := req.OldRef
	if oldRef == "" {
		oldRef = req.OldRefLegacy // fall back so an old_ref-only client CASes from the ref it merged against
	}
	newRef, version, changed, err := s.store.Advance(r.Context(), repoID, branch, oldRef, req.Data, store.Attribution{AccountID: caller.AccountID, Handle: caller.Handle})
	switch {
	case errors.Is(err, store.ErrConflict):
		writeJSONError(w, http.StatusPreconditionFailed, "fact-set head changed; re-read and re-merge")
	case err != nil:
		s.logger.Error().Err(err).Msg("advance")
		// identity/parse failures are the caller's data, not our fault
		if strings.Contains(err.Error(), "factset:") {
			writeJSONError(w, http.StatusBadRequest, "invalid fact set")
			return
		}
		writeJSONError(w, http.StatusInternalServerError, "internal error")
	default:
		writeJSON(w, http.StatusOK, advanceResponse{NewRef: newRef, Version: version, Changed: changed})
	}
}

func validateBranch(branch string) error {
	if branch == "" {
		return errors.New("branch is required")
	}
	if len(branch) > maxBranchBytes {
		return fmt.Errorf("branch exceeds %d bytes", maxBranchBytes)
	}
	return nil
}
```

