// TestConvergenceTwoMembers drives two concurrent clients through the real
// read→merge→advance loop (factmerge.Upsert as the merge, exactly what the
// released client's keep-both Promote reduces to for disjoint facts) and
// asserts the lost-update property: both facts land, version >= 2.
func TestConvergenceTwoMembers(t *testing.T) {
	s, repoID := testServer(t)
	syncOne := func(text string) {
		for attempt := 0; attempt < 32; attempt++ {
			ref, data := getHead(t, s, repoID, "main") // "" / nil when not found
			head := []factmerge.Record{}
			if data != nil {
				var err error
				head, err = factmerge.ParseNDJSON(data)
				if err != nil {
					t.Error(err)
					return
				}
			}
			merged := factmerge.Upsert(head, record(t, text))
			blob, err := factmerge.WriteNDJSON(merged)
			if err != nil {
				t.Error(err)
				return
			}
			if code := tryAdvance(t, s, repoID, ref, blob); code == 200 {
				return
			} else if code != http.StatusPreconditionFailed {
				t.Errorf("unexpected advance status %d", code)
				return
			}
		}
		t.Error("exhausted CAS retries")
	}
	var wg sync.WaitGroup
	for _, text := range []string{"member one's fact", "member two's fact"} {
		wg.Add(1)
